#!/bin/sh
# check-vendor.sh — compare the committed copies with the herdr-shared submodule.
# The copies are generated by the submodule's tools/vendor.sh; never hand-edit them here.
set -u
REPO=$(cd "$(dirname "$0")/.." && pwd)
SHARED=${HERDR_SHARED:-$REPO/vendor/herdr-shared}
if [ ! -f "$SHARED/tools/check-vendor.sh" ]; then
  printf 'check-vendor: herdr-shared is not initialized at %s; run git submodule update --init\n' "$SHARED" >&2
  exit 0
fi
exec sh "$SHARED/tools/check-vendor.sh" "$REPO"
